import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

// Story F2 — typography, checked in the layout and stylesheet source.
//
// Space Grotesk is gone from the app's font loading and tokens. Each text
// style is declared once inside @theme (so Tailwind generates its `text-*`
// utility) with a font-weight and a line-height sub-token. The exact
// resolved values are checked in the browser by e2e/text-styles.spec.ts.
// Do not edit this file to match an implementation.

const TEXT_STYLES = [
  'label',
  'title-1',
  'title-2',
  'title-3',
  'title-4',
  'button-large',
  'button-normal',
  'body-large',
  'body-normal',
  'body-small',
  'hint-number',
  'cell-letter',
  'cell-number',
];

function source(file: string) {
  return readFileSync(new URL(file, import.meta.url), 'utf8');
}

function themeDeclarations() {
  const css = source('./globals.css').replace(/\/\*[\s\S]*?\*\//g, '');
  const names: string[] = [];
  for (const match of css.matchAll(/@theme\b[^{]*\{/g)) {
    const start = match.index! + match[0].length;
    const body = css.slice(start, css.indexOf('}', start));
    for (const decl of body.matchAll(/(--[\w-]+)\s*:/g)) names.push(decl[1]);
  }
  return names;
}

describe('F2 typeface', () => {
  it('loads no Space Grotesk in the layout or the stylesheet', () => {
    for (const file of ['./layout.tsx', './globals.css']) {
      const text = source(file);
      expect(text, file).not.toMatch(/Space_Grotesk|space-grotesk|Space Grotesk/);
    }
  });
});

describe('F2 text styles', () => {
  it('declares each style once in @theme with a weight and a line height', () => {
    const names = themeDeclarations();

    for (const style of TEXT_STYLES) {
      for (const token of [
        `--text-${style}`,
        `--text-${style}--font-weight`,
        `--text-${style}--line-height`,
      ]) {
        expect(names.filter((n) => n === token), token).toHaveLength(1);
      }
    }
  });
});
